CREATE TABLE cloud_canvas_edges(project_id text NOT NULL REFERENCES cloud_projects(id),source_id text NOT NULL,target_id text NOT NULL,label text NOT NULL CHECK(label IN ('casts','uses','reference')),created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(project_id,source_id,target_id,label),FOREIGN KEY(project_id,source_id) REFERENCES cloud_studio_entities(project_id,id)ON DELETE CASCADE,FOREIGN KEY(project_id,target_id)REFERENCES cloud_studio_entities(project_id,id)ON DELETE CASCADE,CHECK(source_id<>target_id));
